            reject: [{ re: '^the advantages outweigh the disadvantages$', hint: 'The same words as your introduction: restate your verdict in new words.' },
              { re: 'as (beneficial|helpful|good|useful) as|equally|evenly|balanced', hint: 'That sits on the fence. Say which side is heavier.' },
              { re: 'more harmful than|(disadvantages|drawbacks|risks|harms|costs) (clearly )?outweigh', hint: 'That changes side: your verdict favours the advantages.' }],
